// Deterministic browser mirrors; the two JSON files are frozen release sources.
const fs = require("node:fs"),
  path = require("node:path");
for (const [file, global] of [
  ["player-materials", "mapGamePlayerMaterials"],
  ["research", "mapGameResearchData"],
]) {
  const data = JSON.parse(
    fs.readFileSync(path.join(__dirname, file + ".json"), "utf8"),
  );
  fs.writeFileSync(
    path.join(__dirname, file + "-data.js"),
    "// Generated by industrial/build-progression.cjs; edit the versioned JSON source.\n(function(r){const d=" +
      JSON.stringify(data) +
      ';if(typeof module!=="undefined")module.exports=d;else r.' +
      global +
      "=d;})(globalThis);\n",
  );
}
